const usagePoints = (consumed, included, peak) => {
  const consumedUnits = BigInt(consumed);
  const includedUnits = BigInt(included);
  const standardUnits = consumedUnits < includedUnits ? consumedUnits : includedUnits;
  const excessUnits = consumedUnits > includedUnits ? consumedUnits - includedUnits : 0n;
  const excessRate = peak ? 7n : 4n;
  return standardUnits * 2n + excessUnits * excessRate;
};
export async function loadParley() { return { usage_points: usagePoints }; }

