from pydantic import BaseModel, ConfigDict, Field


class RequestInput(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    dryness_points: int = Field(ge=0)
    tree_rows: int = Field(ge=0)
    rain_expected: bool


def raw_irrigation(dryness_points: int, tree_rows: int) -> int:
    return dryness_points * tree_rows * 2


def rain_credit(tree_rows: int, rain_expected: bool) -> int:
    return tree_rows * 5 if rain_expected else 0


def scheduled_irrigation(dryness_points: int, tree_rows: int, rain_expected: bool) -> int:
    return max(raw_irrigation(dryness_points, tree_rows) - rain_credit(tree_rows, rain_expected), 0)


def irrigation_cycles(dryness_points: int, tree_rows: int, rain_expected: bool) -> int:
    scheduled = scheduled_irrigation(dryness_points, tree_rows, rain_expected)
    return (scheduled + 39) // 40


def handle(value: RequestInput) -> dict[str, object]:
    raw = raw_irrigation(value.dryness_points, value.tree_rows)
    credit = rain_credit(value.tree_rows, value.rain_expected)
    scheduled = scheduled_irrigation(value.dryness_points, value.tree_rows, value.rain_expected)
    return {"raw_liters": raw, "rain_credit_liters": credit, "scheduled_liters": scheduled, "pump_cycles": irrigation_cycles(value.dryness_points, value.tree_rows, value.rain_expected), "mode": "idle" if scheduled == 0 else "active"}

