const irrigationCycles = (drynessPoints, treeRows, rainExpected) => {
  const dryness = BigInt(drynessPoints);
  const rows = BigInt(treeRows);
  const rawLiters = dryness * rows * 2n;
  const rainCreditLiters = rainExpected ? rows * 5n : 0n;
  const scheduledLiters = rawLiters > rainCreditLiters
    ? rawLiters - rainCreditLiters
    : 0n;
  return (scheduledLiters + 39n) / 40n;
};
export async function loadParley() { return { irrigation_cycles: irrigationCycles }; }

