const irrigationCycles = (drynessPoints, treeRows, rainExpected) => {
  const rawLiters = drynessPoints * treeRows * 2;
  const rainCreditLiters = rainExpected ? treeRows * 5 : 0;
  const scheduledLiters = Math.max(rawLiters - rainCreditLiters, 0);
  return Math.ceil(scheduledLiters / 40);
};
export async function loadParley() { return { irrigation_cycles: irrigationCycles }; }

