async fn browser_module() -> Response { let mut response = BROWSER_MODULE.into_response(); response.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("text/javascript; charset=utf-8")); response }
#[tokio::main] async fn main() {
    let wasm = env::var_os("FULLSTACK_037_WASM").map(std::path::PathBuf::from).unwrap();
    let app = Router::new().route("/health/ready", get(status)).route("/v1/usage-points", post(endpoint)).route("/api/{*rest}", any(missing_api)).route("/parley.js", get(browser_module)).route_service("/fullstack_agent_037.wasm", ServeFile::new(wasm)).fallback_service(ServeDir::new("public").append_index_html_on_directories(true));
